class GenerateLoanLetterAndAgreementModule_AutoGenerated {
  /*find the loan account which id is load account id and if it's not exist, then create loan account with loanaccountid, balance, status provided*/
  createLoanAccount(
    loanaccountid: number,
    balance: number,
    status: LoanAccountStatus,
  ): boolean {
    /*Definition Start*/
    let loanAccount: LoanAccount = l({
      logic: () =>
        getRepository(LoanAccount).find(
          (_l: any) =>
            l({
              logic: () => _l.LoanAccountID === loanaccountid,
              description: "l.LoanAccountID=loanaccountid",
            }).build().pass,
        ),
      description:
        "LoanAccount.allInstance()->any(l|l.LoanAccountID=loanaccountid)",
    }).build().pass;
    let isExisted: boolean = l()
      .if({
        logic: () =>
          l({
            logic: () => StandardOPs.oclIsUndefined(loanAccount),
            description: "loanAccount.oclIsUndefined()",
          }),
        description: "loanAccount.oclIsUndefined()",
        then: l({
          logic: () => false,
          description: "false",
        }),
        else: l({
          logic: () => true,
          description: "true",
        }),
      })
      .build().pass;
    /*Definition End*/

    /*Precondition Start*/
    const { errorMessage: preconditionErrorMessage, pass: isPreconditionPass } =
      l({
        logic: () => StandardOPs.oclIsTypeOf(loanaccountid, Integer),
        description: "loanaccountid.oclIsTypeOf(Integer)",
      })
        .and({
          logic: () => StandardOPs.oclIsTypeOf(balance, Real),
          description: "balance.oclIsTypeOf(Real)",
        })
        .and({
          logic: () => StandardOPs.oclIsTypeOf(status, LoanAccountStatus),
          description: "status.oclIsTypeOf(LoanAccountStatus)",
        })
        .build();
    if (!isPreconditionPass) {
      throw new PreconditionError(preconditionErrorMessage);
    }
    /*Precondition End*/

    /*Postcondition Start*/
    return l({
      execute: () => (isExisted = true),
      description: "isExisted=true",
    })
      .and({
        execute: () => true,
        description: "result=true",
      })
      .or({
        execute: () => (isExisted = false),
        description: "isExisted=false",
      })
      .and({
        execute: () => getRepository(LoanAccount).push(loanAccount),
        description: "LoanAccount.allInstance()->includes(loanAccount)",
      })
      .and({
        execute: () => (loanAccount = new LoanAccount()),
        description: "loanAccount.oclIsNew()",
      })
      .and({
        execute: () => (loanAccount.LoanAccountID = loanaccountid),
        description: "loanAccount.LoanAccountID=loanaccountid",
      })
      .and({
        execute: () => (loanAccount.Balance = balance),
        description: "loanAccount.Balance=balance",
      })
      .and({
        execute: () => (loanAccount.Status = status),
        description: "loanAccount.Status=status",
      })
      .and({
        execute: () => true,
        description: "result=true",
      })
      .build().value;
    /*Postcondition End*/
  }
}
export { GenerateLoanLetterAndAgreementModule_AutoGenerated };

